using GSPTaskMiningAnalyzer.Models; namespace GSPTaskMiningAnalyzer; public sealed class DurationCalculator { public double MaxGapSeconds{get;init;}=60; public List<(LogEvent Event,double Seconds)> Calculate(IReadOnlyList<LogEvent> events){var r=new List<(LogEvent,double)>(); for(int i=0;i<events.Count;i++){var e=events[i]; var s=e.DurationSeconds is >0 and <=86400 ? e.DurationSeconds.Value : (i+1<events.Count ? (events[i+1].TimestampUtc-e.TimestampUtc).TotalSeconds : 0); if(s<0||s>MaxGapSeconds)s=0; r.Add((e,s));} return r;}}
